// The global-search route (browse-scale D7/D3): the cmd-built browse index
// answers the RANKED hit ids per group — ids only, the honesty backstop —
// and this handler maps them to live rows and composes every display byte
// fresh through the existing per-library DTO seams, memoizing ONE namer per
// DISTINCT RESULT LIBRARY per request (D3, reviewer Q7: the bound is
// "distinct result libraries", not ≤2). Per-user visibility lives entirely
// at serve time: hits are read through the caller's Viewer, so a row in an
// invisible library reads exactly like a missing row and drops silently —
// the index itself stays shared/full (D2: built via access.System() at
// rebuild), never per-user.

package api

import (
	"context"
	"database/sql"
	"errors"
	"net/http"
	"strconv"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// searchMaxPerGroup is the D7 wire bound: each result group serves at most
// eight entries (global-search spec). The index bounds its ranked lists at
// its own internal max; api never imports that package (D2 — serve closures
// only), so the wire bound is stated here where it is enforced — a client
// ?limit= can lower it, never raise it.
const searchMaxPerGroup = 8

// searchResponse is the wire shape for GET /search (browse-scale D7): the
// two bounded groups, each entry the SAME grid DTO the /series and /items
// listings serve, composed live at request time (the index decided only
// WHICH ids match). Both arrays are always present — empty when nothing
// matched, because no match is 200 empty, never an error.
type searchResponse struct {
	Series []seriesDTO `json:"series"`
	Items  []itemDTO   `json:"items"`
}

// search serves GET /api/v1/search (browse group): the grouped ranked
// search over the composed-name index. Empty or absent q is an empty
// success (browsing is the facets' job); a query matching nothing is 200
// with both lists empty, never an error. Photos are excluded v1 by the
// index corpus (media libraries only — OQ1), never by a handler filter.
// A malformed present ?library= or ?limit= is 400 bad_request; absent
// means unscoped (the caller's visibility conjunct still applies) and the
// full 8-entry group bound.
//
// @Summary      Global grouped search over composed names
// @Tags         search
// @ID           search
// @Router       /search [get]
// @Param        q       query string false "query text; empty or absent serves both lists empty"
// @Param        library query int    false "restrict results to one library id"
// @Param        limit   query int    false "per-group bound (default 8, max 8 — lowers the bound, never raises it)"
// @Success      200 {object} searchResponse
// @Failure      400 {object} errorBody
// @Failure      500 {object} errorBody
func (a *app) search(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query().Get("q")
	scope, bad := parseSearchLibrary(r)
	if bad != "" {
		writeError(w, http.StatusBadRequest, "bad_request", bad, false)
		return
	}
	limit, bad := parseSearchLimit(r)
	if bad != "" {
		writeError(w, http.StatusBadRequest, "bad_request", bad, false)
		return
	}
	// The caller's scope (6.2, the browse-group convention): the hit rows
	// and the composed names ride the requesting viewer — hits in invisible
	// libraries never surface, and the walk mutes past this viewer's
	// muted sources exactly like the other browse routes.
	v, ctx := a.viewerFor(r)
	seriesIDs, itemIDs := a.searchHits(q)
	seriesRows, err := a.searchSeriesRows(ctx, v, seriesIDs, scope)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	itemRows, err := a.searchItemRows(ctx, v, itemIDs, scope)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	if len(seriesRows) > limit {
		seriesRows = seriesRows[:limit]
	}
	if len(itemRows) > limit {
		itemRows = itemRows[:limit]
	}
	namers := map[int64]naming.Namer{}
	series, err := a.searchSeriesDTOs(ctx, v, seriesRows, namers)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	items, err := a.searchItemDTOs(ctx, v, itemRows, namers)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusOK, searchResponse{Series: series, Items: items})
}

// parseSearchLibrary reads the optional ?library= scope: absent means all
// libraries (the viewer's visibility conjunct still applies). A present
// non-integer is a 400 — the listItems strictness — because a typo'd id
// silently widening the query to every library is exactly the surprise an
// optional scope must never carry.
func parseSearchLibrary(r *http.Request) (*int64, string) {
	raw := r.URL.Query().Get("library")
	if raw == "" {
		return nil, ""
	}
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return nil, "library query param must be an integer"
	}
	return &id, ""
}

// parseSearchLimit reads the optional ?limit= per-group bound: absent means
// the 8-entry wire bound; a present value is a client-asked REDUCTION of
// it (the 8+8 shape is the route's design bound, so a larger ask clamps,
// the parsePagination posture), while a present non-integer or non-positive
// is a 400 bad_request (the listProgress strictness for a PRESENT bad
// value).
func parseSearchLimit(r *http.Request) (int, string) {
	raw := r.URL.Query().Get("limit")
	if raw == "" {
		return searchMaxPerGroup, ""
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n <= 0 {
		return 0, "limit query param must be a positive integer"
	}
	return min(n, searchMaxPerGroup), ""
}

// searchHits runs the cmd-built hit closure (Deps.BrowseSearch) — the
// ranked hit ids per group for one query. Nil-safe (the Deps contract): a
// nil closure answers empty, the same honest never-built floor the browse
// service itself serves. An empty query skips the closure entirely — the
// spec's empty-q contract is an empty success before any read runs.
func (a *app) searchHits(q string) (seriesIDs, itemIDs []string) {
	if q == "" || a.deps.BrowseSearch == nil {
		return nil, nil
	}
	return a.deps.BrowseSearch(q)
}

// searchSeriesRows loads the series hit rows in the served ranked order,
// read through the caller's Viewer. A hit whose row no longer exists (a
// stale index can only degrade recall) or sits in an invisible library
// reads as sql.ErrNoRows and drops silently — nothing leaks, not even
// existence. Any other read error propagates (500 at the call site). The
// optional scope drops rows outside the requested library.
func (a *app) searchSeriesRows(ctx context.Context, v access.Viewer, ids []string, scope *int64) ([]store.Series, error) {
	rows := make([]store.Series, 0, len(ids))
	for _, id := range ids {
		sr, err := a.deps.Store.GetSeries(ctx, id, v)
		if errors.Is(err, sql.ErrNoRows) {
			continue
		}
		if err != nil {
			return nil, err
		}
		if scope != nil && sr.LibraryID != *scope {
			continue
		}
		rows = append(rows, sr)
	}
	return rows, nil
}

// searchItemRows is searchSeriesRows over the item hit group — same
// visibility conjunct, same silent drop, same error propagation.
func (a *app) searchItemRows(ctx context.Context, v access.Viewer, ids []string, scope *int64) ([]store.Item, error) {
	rows := make([]store.Item, 0, len(ids))
	for _, id := range ids {
		it, err := a.deps.Store.GetItem(ctx, id, v)
		if errors.Is(err, sql.ErrNoRows) {
			continue
		}
		if err != nil {
			return nil, err
		}
		if scope != nil && it.LibraryID != *scope {
			continue
		}
		rows = append(rows, it)
	}
	return rows, nil
}

// searchNamer returns the request's memoized namer for one result library:
// ONE namerFor call per DISTINCT library per request (D3, reviewer Q7),
// the mutes riding the calling Viewer's ChainMutes (10.4 — names mute
// exactly like the other browse routes).
func (a *app) searchNamer(ctx context.Context, memo map[int64]naming.Namer, libraryID int64, mutes map[string]bool) (naming.Namer, error) {
	if n, ok := memo[libraryID]; ok {
		return n, nil
	}
	n, err := a.namerFor(ctx, libraryID, mutes)
	if err != nil {
		return naming.Namer{}, err
	}
	memo[libraryID] = n
	return n, nil
}

// searchSeriesDTOs composes the served series rows through the existing
// seriesDTOs seam — batched per DISTINCT RESULT LIBRARY, because that seam
// is per-library (one namer, one artwork scope per call), then
// reassembled in the served ranked order. The namer memo is shared across
// both groups so a library hit in both pays for its namer once.
func (a *app) searchSeriesDTOs(ctx context.Context, v access.Viewer, rows []store.Series, namers map[int64]naming.Namer) ([]seriesDTO, error) {
	out := make([]seriesDTO, len(rows))
	byLib := map[int64][]int{}
	for i, sr := range rows {
		byLib[sr.LibraryID] = append(byLib[sr.LibraryID], i)
	}
	for libID, idxs := range byLib {
		n, err := a.searchNamer(ctx, namers, libID, v.ChainMutes)
		if err != nil {
			return nil, err
		}
		batch := make([]store.Series, len(idxs))
		for j, i := range idxs {
			batch[j] = rows[i]
		}
		dtos, err := a.seriesDTOs(ctx, batch, n, v.ChainMutes)
		if err != nil {
			return nil, err
		}
		for j, d := range dtos {
			out[idxs[j]] = d
		}
	}
	return out, nil
}

// searchItemDTOs is searchSeriesDTOs over the item group — the itemDTOs
// seam, batched per distinct result library against the SAME shared namer
// memo, reassembled in the served ranked order.
func (a *app) searchItemDTOs(ctx context.Context, v access.Viewer, rows []store.Item, namers map[int64]naming.Namer) ([]itemDTO, error) {
	out := make([]itemDTO, len(rows))
	byLib := map[int64][]int{}
	for i, it := range rows {
		byLib[it.LibraryID] = append(byLib[it.LibraryID], i)
	}
	for libID, idxs := range byLib {
		n, err := a.searchNamer(ctx, namers, libID, v.ChainMutes)
		if err != nil {
			return nil, err
		}
		batch := make([]store.Item, len(idxs))
		for j, i := range idxs {
			batch[j] = rows[i]
		}
		dtos, err := a.itemDTOs(ctx, batch, n, v.ChainMutes)
		if err != nil {
			return nil, err
		}
		for j, d := range dtos {
			out[idxs[j]] = d
		}
	}
	return out, nil
}
